_PROFILE_KEYED_FIELDS = ("birth_date", "birth_time", "birth_time_mode")


def apply_profile_key_presence(payload, data: dict) -> dict:
    """요청에 키가 없는 필드는 저장 대상에서 빼서 기존 값을 유지한다.

    PUT /me/profile 은 "전체 교체"지만, 구버전 클라이언트는 새 필드를 모른 채
    요청을 보낸다. `model_dump()` 는 생략된 필드를 기본값(None)으로 채우므로,
    그대로 저장하면 기존 값이 NULL 로 지워진다.
      - 키 없음        → 저장 대상에서 제외(기존 값 유지)
      - 키 있고 null   → 그대로 저장(명시적 삭제)

    `feat/mbti-contrast` 브랜치의 동일 헬퍼와 시그니처/이름을 맞춰
    병합 충돌을 최소화한다(그 브랜치는 `_PROFILE_KEYED_FIELDS` 에 "mbti" 추가).
    """
    fields_set = getattr(payload, "model_fields_set", set())
    for name in _PROFILE_KEYED_FIELDS:
        if name not in fields_set:
            data.pop(name, None)
    return data


def _check_birth_time_combination(mode, time_value):
    """`birth_time_mode` 와 `birth_time` 의 모순 조합을 422 로 거부한다.

    보낸 필드가 하나뿐이면(생략) 기존 값과 합쳐질 수 있으므로 검사하지 않는다.
    """
    if mode == "exact" and not time_value:
        raise HTTPException(
            status_code=422,
            detail="birth_time is required when birth_time_mode='exact'.",
        )
    if mode in ("noon", "day_only") and time_value:
        raise HTTPException(
            status_code=422,
            detail=f"birth_time must be null when birth_time_mode='{mode}'.",
        )


@router.get("/me/profile", response_model=ProfileResponse)
def get_my_profile(user: dict = Depends(get_current_user)):
    profile = get_repository().get_profile(user["id"])
    if profile is None:
        raise HTTPException(status_code=404, detail="Profile not found.")
    # 🆕 예전 프로필 (필드 누락) 방어
    d = dict(profile)
    defaults = {
        "timezone_str": "Asia/Seoul",
        "longitude": 126.978,
        "gender": "M",
        "jasi_boundary": 23,
        "correction_mode": "lmt",
    }
    for k, v in defaults.items():
        if d.get(k) is None:
            d[k] = v
    return d


@router.put("/me/profile", response_model=ProfileResponse)
def upsert_my_profile(
    payload: ProfilePayload,
    user: dict = Depends(get_current_user),
):
    data = apply_profile_key_presence(payload, payload.model_dump())

    # 두 키가 모두 왔을 때만 조합 모순을 판정한다(한쪽 생략 = 기존 값과 합쳐짐).
    fields_set = payload.model_fields_set
    if "birth_time" in fields_set and "birth_time_mode" in fields_set:
        _check_birth_time_combination(payload.birth_time_mode, payload.birth_time)

    try:
        return get_repository().upsert_profile(user["id"], data)
    except DobChangeLimitExceeded as e:
        raise HTTPException(status_code=409, detail=e.message)


@router.post("/link/{provider}", response_model=TokenResponse)
def link_provider(
    provider: str,
    body: LinkRequest,
    user: dict = Depends(get_current_user),
):
    """익명 세션을 소셜 계정으로 승격. 실패 시 400/409."""
    try:
        identity = verify_provider_token(provider, body.provider_token)
    except ProviderTokenError as e:
        raise HTTPException(status_code=400, detail=str(e))

    try:
        updated = get_repository().link_social_identity(
            user["id"], identity["provider"], identity["subject"],
        )
    except ValueError as e:
        raise HTTPException(status_code=409, detail=str(e))

    token = encode_token(updated["id"])
    return {
        "access_token": token,
        "token_type": "bearer",
        "expires_in": ttl_seconds(),
        "user": _user_public(updated),
    }


@router.post("/login/telegram", response_model=TokenResponse)
def login_telegram(
    payload: TelegramInitData, 
    current_user: dict | None = Depends(get_current_user_optional)
):
    from app.auth.jwt_utils import encode_token, ttl_seconds
    from app.auth.repository import get_repository
    
    tg_id = _verified_telegram_id(payload)
    repo = get_repository()
    
    # 1. 텔레그램 ID로 기존 유저 찾기
    user = repo.get_user_by_telegram_id(tg_id)
    
    # 2. 분기 처리
    if user:
        # 이미 텔레그램 연동된 계정이 있음 (정상 로그인)
        pass
    elif current_user:
        # 텔레그램 연동은 안 되어 있지만, 현재 로그인된(게스트/프리미엄) 계정이 있음 -> 이 계정에 연동!
        user = current_user
        repo.upsert_telegram_subscriber(tg_id, user["id"], payload.lang or "ko")
        repo.set_user_not_anonymous(user["id"])
    else:
        # 텔레그램도 없고 현재 세션도 없음 -> 완전 신규 생성
        user = repo.create_anonymous_user()
        repo.upsert_telegram_subscriber(tg_id, user["id"], payload.lang or "ko")
        repo.set_user_not_anonymous(user["id"])
        
    # 최신 정보 갱신
    user = repo.get_user(user["id"])
    token = encode_token(user["id"])
    
    return {
        "access_token": token,
        "token_type": "bearer",
        "expires_in": ttl_seconds(),
        "user": _user_public(user),
    }
@router.post("/login/{provider}", response_model=TokenResponse)
def login_provider(provider: str, body: LoginRequest):
    """이미 링크된 소셜 identity 로 로그인. 없으면 404."""
    try:
        identity = verify_provider_token(provider, body.provider_token)
    except ProviderTokenError as e:
        raise HTTPException(status_code=400, detail=str(e))

    user = get_repository().find_user_by_social(
        identity["provider"], identity["subject"],
    )
    if user is None:
        raise HTTPException(
            status_code=404,
            detail=(
                f"No account linked to this {identity['provider']} identity. "
                f"Create an anonymous session first, then "
                f"POST /api/v1/auth/link/{identity['provider']}."
            ),
        )

    token = encode_token(user["id"])
    return {
        "access_token": token,
        "token_type": "bearer",
        "expires_in": ttl_seconds(),
        "user": _user_public(user),
    }


@router.post("/me/push-token")
def register_push_token(
    payload: PushTokenPayload,
    user: dict = Depends(get_current_user),
):
    """푸시 토큰 등록. 인증된 모든 유저 가능 (구독 안 해도 등록은 OK)."""
    get_repository().register_push_token(
        user["id"], payload.token, payload.platform, payload.device_id,
    )
    return {"registered": True, "tokens": len(get_repository().list_push_tokens(user["id"]))}


@router.delete("/me/push-token")
def unregister_push_token(
    payload: PushTokenPayload,
    user: dict = Depends(get_current_user),
):
    """푸시 토큰 해지. 로그아웃·기기 변경 시 호출."""
    removed = get_repository().unregister_push_token(user["id"], payload.token)
    return {"removed": removed}


